import{_ as n,o as t,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Liste der Vorschläge für erweiterte Einstellungen","description":"","frontmatter":{},"headers":[],"relativePath":"de/98-扩展设定建议清单.md","filePath":"de/98-扩展设定建议清单.md","lastUpdated":null}'),s={name:"de/98-扩展设定建议清单.md"};function d(u,e,l,a,o,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="liste-der-vorschlage-fur-erweiterte-einstellungen" tabindex="-1">Liste der Vorschläge für erweiterte Einstellungen <a class="header-anchor" href="#liste-der-vorschlage-fur-erweiterte-einstellungen" aria-label="Permalink to &quot;Liste der Vorschläge für erweiterte Einstellungen&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Punkt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>98</td></tr><tr><td>Modul</td><td>Anhänge und Referenzmaterialien</td></tr><tr><td>Schlüsselwörter</td><td>erweiterte Einstellungen, kreative Vorschläge, Einstellungsrichtung, Offenheit, noch zu entwickelnde Bereiche</td></tr></tbody></table><h2 id="_1-beschreibung" tabindex="-1">1. Beschreibung <a class="header-anchor" href="#_1-beschreibung" aria-label="Permalink to &quot;1. Beschreibung&quot;">​</a></h2><p>Dieses Dokument listet die Richtungen und Vorschläge für die erweiterte Kreation im Einstellungssystem der Anker-Symbiose-Zivilisation auf, mit dem Ziel, Einstellungsschöpfern Inspiration und Anleitung zu geben und ihnen zu helfen, wertvolle Einstellungserweiterungen innerhalb des bestehenden Rahmens durchzuführen. Diese Liste ist nach Modulen klassifiziert, und jede Erweiterungsrichtung enthält eine Beschreibung der Richtung, den Wert der Erweiterung, die Beziehung zu bestehenden Einstellungen und kreative Vorschläge. Es ist wichtig zu betonen, dass diese Liste nur eine beratende Referenz ist; Schöpfer können unter der Voraussetzung, die Konsistenz der Einstellungen einzuhalten, frei kreativ tätig werden oder auch völlig neue Richtungen entwickeln, die nicht in dieser Liste enthalten sind. Alle erweiterten Einstellungen müssen vor der formellen Aufnahme die Prüfung des Dokuments 97 &quot;Selbstprüfungstabelle für Einstellungswidersprüche&quot; bestehen.</p><h2 id="_2-erweiterungsrichtungen-der-weltanschauung-und-der-kerneinstellungen" tabindex="-1">2. Erweiterungsrichtungen der Weltanschauung und der Kerneinstellungen <a class="header-anchor" href="#_2-erweiterungsrichtungen-der-weltanschauung-und-der-kerneinstellungen" aria-label="Permalink to &quot;2. Erweiterungsrichtungen der Weltanschauung und der Kerneinstellungen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nummer</th><th>Erweiterungsrichtung</th><th>Wert der Erweiterung</th><th>Zugehörige Einstellung</th><th>Kreativer Vorschlag</th></tr></thead><tbody><tr><td>E01</td><td>Existenz jenseits der Grenzen des Universums</td><td>Erforschung, ob außerhalb des Gesetzesnetzwerks von Hengyuanzhou andere Universen oder Wesen höherer Dimensionen existieren, um eine grandiosere Universumsansicht für die Einstellungen zu liefern</td><td>Dokument 00, Dokument 28</td><td>Man kann die Existenz der &quot;Universumswand&quot; und die Geschichten weniger Entdecker, die die Universumswand durchbrochen haben, einstellen, um Hinweise für zukünftige Interaktionen zwischen Universen zu hinterlassen</td></tr><tr><td>E02</td><td>Das Wesen des Universumswillens</td><td>Tiefgehende Erörterung, ob in der untersten Schicht des Gesetzesnetzwerks ein &quot;Universumswille&quot; existiert und wie er mit dem Ankermechanismus zusammenhängt</td><td>Dokument 00, Dokument 20</td><td>Man kann den Universumswillen als ein nicht personalisiertes Phänomen der Selbstorganisation von Gesetzen einstellen, nicht als eine bestimmte Gottheit, und die Position &quot;auf der Realität basierend&quot; beibehalten</td></tr><tr><td>E03</td><td>Verlorene Zivilisationen der Vor-Anker-Ära</td><td>Detaillierte Einstellung von Zivilisationen, die in der Vor-Anker-Ära einst blühten, aber untergegangen sind, um die historische Tiefe zu bereichern</td><td>Dokument 71, Dokument 93</td><td>Man kann 3-5 repräsentative verlorene Zivilisationen einstellen, jede mit ihrem eigenen einzigartigen Kultivierungssystem, ihrer Kultur und ihrem Untergangsgrund, um Material für archäologische Einstellungen zu liefern</td></tr><tr><td>E04</td><td>Philosophische Schulen des Symbiosekonzepts</td><td>Unter dem großen Rahmen &quot;Anti-Plünderung, Befürwortung der Symbiose&quot; die unterschiedlichen Interpretationen verschiedener philosophischer Schulen zum Konzept der Symbiose einstellen</td><td>Dokument 04, Dokument 03</td><td>Man kann Schulen wie die &quot;radikale Symbioseschule&quot;, die &quot;gemäßigte Symbioseschule&quot;, die &quot;ökologische Symbioseschule&quot;, die &quot;technologische Symbioseschule&quot; einstellen, und der ideologische Kampf zwischen ihnen kann zu einer wichtigen Handlungsspannung werden</td></tr></tbody></table><h2 id="_3-erweiterungsrichtungen-des-kultivierungssystems" tabindex="-1">3. Erweiterungsrichtungen des Kultivierungssystems <a class="header-anchor" href="#_3-erweiterungsrichtungen-des-kultivierungssystems" aria-label="Permalink to &quot;3. Erweiterungsrichtungen des Kultivierungssystems&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nummer</th><th>Erweiterungsrichtung</th><th>Wert der Erweiterung</th><th>Zugehörige Einstellung</th><th>Kreativer Vorschlag</th></tr></thead><tbody><tr><td>E05</td><td>Detaillierte Methoden eines einzelnen Systems</td><td>Detaillierte Ausarbeitung eines der dreihundert Systeme, einschließlich spezifischer Kultivierungsmethoden, Methoden zum Durchbrechen von Reichen, häufigen Irrtümern usw.</td><td>Dokument 10-19, Dokument 91</td><td>Es wird empfohlen, vorrangig die drei Grundlagen und die Systeme der Kategorie der angewandten Technik, die eng mit der Technologie verbunden sind, auszuarbeiten; das detaillierte Dokument jedes Systems kann Kultivierungsschritte, mentale Formeln, Ressourcenbedarf, Risikowarnungen usw. enthalten</td></tr><tr><td>E06</td><td>Kombinationspläne für die gleichzeitige Kultivierung mehrerer Systeme</td><td>Erforschung der Kompatibilität der gleichzeitigen Kultivierung zwischen verschiedenen Systemen und Gestaltung optimaler Multi-System-Kombinationspläne</td><td>Dokument 10, Dokument 11-13</td><td>Man kann &quot;goldene Kombinationen&quot; (wie Deduktionsiteration + Raumgesetze + angewandte Technik) und verschiedene exotische Kombinationen einstellen und die Vorteile und Grenzen jeder Kombination analysieren</td></tr><tr><td>E07</td><td>Kultivierungsengpässe und Durchbruchsmethoden</td><td>Detaillierte Einstellung der Engpässe, auf die jedes System in verschiedenen Reichen stoßen kann, und verschiedener Methoden zum Durchbrechen der Engpässe</td><td>Dokument 14, Dokument 19</td><td>Man kann verschiedene Arten von Engpässen wie &quot;Herzensdämonen-Tribulation&quot;, &quot;Gesetzesbarriere&quot;, &quot;Ursprungsobstruktion&quot; und die entsprechenden Durchbruchswege einstellen, um die Hierarchie des Kultivierungsprozesses zu erhöhen</td></tr><tr><td>E08</td><td>Besondere Konstitutionen und Systemanpassung</td><td>Einstellung verschiedener besonderer Konstitutionen (wie angeborene Dao-Konstitution, elementaffiner Körper, bewusstseinsempfindlicher Körper usw.) und ihrer Anpassungsbeziehung zu verschiedenen Kultivierungssystemen</td><td>Dokument 12, Dokument 51</td><td>Man kann eine &quot;Konstitutions-System-Anpassungsmatrix&quot; entwerfen, um Schöpfern zu helfen, schnell zu beurteilen, welche Systeme für eine bestimmte Konstitution geeignet sind</td></tr><tr><td>E09</td><td>Detaillierte Klassifizierung von Kultivierungsressourcen</td><td>Detaillierte Klassifizierung und Einstellung verschiedener für die Kultivierung benötigter Ressourcen (natürliche Schätze, Energiekristalle, Gesetzesfragmente usw.)</td><td>Dokument 18, Dokument 65</td><td>Man kann den Grad, den Herkunftsort, die Sammelmethode, die Aufbewahrungsmethode, die Verwendungsverbote der Ressourcen usw. einstellen und ein vollständiges Ökosystem der Kultivierungsressourcen aufbauen</td></tr></tbody></table><h2 id="_4-erweiterungsrichtungen-des-sozialsystems" tabindex="-1">4. Erweiterungsrichtungen des Sozialsystems <a class="header-anchor" href="#_4-erweiterungsrichtungen-des-sozialsystems" aria-label="Permalink to &quot;4. Erweiterungsrichtungen des Sozialsystems&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nummer</th><th>Erweiterungsrichtung</th><th>Wert der Erweiterung</th><th>Zugehörige Einstellung</th><th>Kreativer Vorschlag</th></tr></thead><tbody><tr><td>E10</td><td>Spezifische Sozialformen der fünf Typen</td><td>Detaillierte Ausarbeitung der spezifischen Sozialsysteme, Wirtschaftsmodelle und kulturellen Merkmale jedes der fünf Typen der Symbiose-Zivilisation</td><td>Dokument 30-35</td><td>Jeder Typ kann seine typische Stadtform, Familienstruktur, Bildungsmodell, Festfeiern usw. einstellen, sodass die fünf Typen jeweils charakteristisch sind</td></tr><tr><td>E11</td><td>Planung und Bau von Symbiose-Städten</td><td>Einstellung des Planungskonzepts, des Baustils, der Infrastruktur und der Funktionszonen von Städten in der Symbiose-Zivilisation</td><td>Dokument 39, Dokument 60</td><td>Man kann verschiedene Arten von Stadtformen wie &quot;vertikale Symbiose-Stadt&quot;, &quot;ökologische verschachtelte Stadt&quot;, &quot;Raumfaltstadt&quot; entwerfen</td></tr><tr><td>E12</td><td>Detaillierter Betrieb des Bildungssystems</td><td>Detaillierte Einstellung des vollständigen Betriebsmechanismus des Symbiose-Bildungssystems, von der Vorschulbildung bis zur Hochschulbildung und Kultivierungsbildung</td><td>Dokument 37, Dokument 43</td><td>Man kann das Curriculum-System, die Bewertungsmethoden, das Mentorsystem, die interrassischen Bildungspläne usw. einstellen</td></tr><tr><td>E13</td><td>Detaillierter Betrieb des medizinischen Systems</td><td>Detaillierte Einstellung des Betriebsmechanismus des Symbiose-medizinischen Systems, einschließlich der Kombination von konventioneller Medizin und Kultivierungsmedizin</td><td>Dokument 38, Dokument 44</td><td>Man kann das Krankenhaussystem, den Erstattungsprozess der Krankenversicherung, die besonderen Normen der Kultivierungsbehandlung, die interrassischen medizinischen Pläne usw. einstellen</td></tr><tr><td>E14</td><td>Soziale Sicherheit und Wohlfahrtssystem</td><td>Detaillierte Einstellung des sozialen Sicherheitssystems der Symbiose-Zivilisation, einschließlich Altersversorgung, Arbeitslosigkeit, Hilfe usw.</td><td>Dokument 32, Dokument 08</td><td>Man kann die Bedingungen für den Bezug von Wohlfahrt, die Verteilungsstandards, die Finanzierungsquellen, die Überwachungsmechanismen usw. einstellen</td></tr></tbody></table><h2 id="_5-erweiterungsrichtungen-von-recht-und-governance" tabindex="-1">5. Erweiterungsrichtungen von Recht und Governance <a class="header-anchor" href="#_5-erweiterungsrichtungen-von-recht-und-governance" aria-label="Permalink to &quot;5. Erweiterungsrichtungen von Recht und Governance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nummer</th><th>Erweiterungsrichtung</th><th>Wert der Erweiterung</th><th>Zugehörige Einstellung</th><th>Kreativer Vorschlag</th></tr></thead><tbody><tr><td>E15</td><td>Typische Rechtsfälle</td><td>Verfassen typischer Fälle, die vom Symbiose-Gericht verhandelt wurden, um die praktische Anwendung des Rechts zu zeigen</td><td>Dokument 40-49, Dokument 92</td><td>Man kann repräsentative Fälle wie &quot;Fall des Monopols auf Kultivierungsressourcen&quot;, &quot;Fall der Entschädigung für interplanare Verschmutzung&quot;, &quot;Fall der Rechte des dunklen Ersetzungskörpers&quot; verfassen</td></tr><tr><td>E16</td><td>Lokales Autonomiesystem</td><td>Detaillierte Einstellung des Autonomiesystems und der Machtverteilung jeder Sternregion, jeder Ebene innerhalb des Verfassungsrahmens</td><td>Dokument 40, Dokument 49</td><td>Man kann die Autonomiemodelle verschiedener autonomer Einheiten, die Beziehung zur Zentralregierung, das Verfahren zur Erlassung von Autonomieverordnungen usw. einstellen</td></tr><tr><td>E17</td><td>Wahl- und Demokratiesystem</td><td>Detaillierte Einstellung des Wahlsystems der Vertreter des Anker-Rats und des demokratischen Entscheidungsmechanismus</td><td>Dokument 32, Dokument 49</td><td>Man kann die Einteilung der Wahlkreise, die Kandidatenqualifikation, das Wahlverfahren, die Abstimmungsmethode, das Amtszeitensystem usw. einstellen</td></tr><tr><td>E18</td><td>Rechtsvollstreckungsmechanismus</td><td>Detaillierte Einstellung des Rechtsvollstreckungsmechanismus, einschließlich Vollstreckungsbehörden, Vollstreckungsverfahren, Zwangsmaßnahmen</td><td>Dokument 48, Dokument 49</td><td>Man kann die Organisationsstruktur der Vollstreckungsbehörden, die Vollstreckungsbefugnisse, das Vollstreckungsverfahren, die Überwachungsmechanismen usw. einstellen</td></tr></tbody></table><h2 id="_6-erweiterungsrichtungen-von-leben-und-rassen" tabindex="-1">6. Erweiterungsrichtungen von Leben und Rassen <a class="header-anchor" href="#_6-erweiterungsrichtungen-von-leben-und-rassen" aria-label="Permalink to &quot;6. Erweiterungsrichtungen von Leben und Rassen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nummer</th><th>Erweiterungsrichtung</th><th>Wert der Erweiterung</th><th>Zugehörige Einstellung</th><th>Kreativer Vorschlag</th></tr></thead><tbody><tr><td>E19</td><td>Detaillierte Einstellung einer einzelnen Rasse</td><td>Detaillierte Ausarbeitung einer Rasse aus dem Katalog aller Rassen, einschließlich physiologischer Merkmale, Sozialstruktur, kultureller Traditionen, historischer Entwicklung</td><td>Dokument 50-52, Dokument 94</td><td>Es wird empfohlen, vorrangig charakteristische Rassen wie die Drachenrasse, die Elfenrasse, die mechanische Rasse, die Bewusstseinswesenrasse auszuarbeiten; jede Rasse kann Sprache, Religion, Kunst, Bräuche usw. enthalten</td></tr><tr><td>E20</td><td>Spezifische Fälle von seltsamem Leben</td><td>Einstellung spezifischer Individuen oder Gruppen von seltsamem Leben, um die praktische Anwendung der drei Arten von Behandlungsverfahren zu zeigen</td><td>Dokument 53-54</td><td>Man kann Fälle von seltsamem Leben wie &quot;Leerendrifter&quot;, &quot;Zeitfragment-Leben&quot;, &quot;Gesetzesparasitenwesen&quot; einstellen</td></tr><tr><td>E21</td><td>Spezifische Arten von seltsamer Energie</td><td>Detaillierte Einstellung der Eigenschaften, Quellen, Verwendungen und Kontrollmethoden verschiedener seltsamer Energien</td><td>Dokument 55-56</td><td>Man kann Arten von seltsamer Energie wie &quot;Kausalenergie&quot;, &quot;Bewusstseinsenergie&quot;, &quot;Zeitnachhallenergie&quot; einstellen</td></tr><tr><td>E22</td><td>Spezifische Fälle von dunklen Ersetzungskörpern</td><td>Einstellung spezifischer individueller Geschichten von dunklen Ersetzungskörpern, um die praktische Anwendung der Doppelseelen-Ethik und der vier Arten von Zweigbehandlungen zu zeigen</td><td>Dokument 57-59</td><td>Man kann Fallgeschichten verschiedener Arten von dunklen Ersetzungskörpern verfassen und das ethische Dilemma der Koexistenz von zwei Seelen erforschen</td></tr><tr><td>E23</td><td>Nachkommen der interrassischen Fusion</td><td>Einstellung der Merkmale und Kultur von Mischrassen, die durch Ehen zwischen verschiedenen Rassen entstehen</td><td>Dokument 52, Dokument 77</td><td>Man kann Mischrassen wie &quot;Halbelfen&quot;, &quot;Drachenmenschen&quot;, &quot;mechanische Biomechanismen&quot; einstellen und ihre Identität und kulturelle Fusion erforschen</td></tr></tbody></table><h2 id="_7-erweiterungsrichtungen-von-technologie-und-energie" tabindex="-1">7. Erweiterungsrichtungen von Technologie und Energie <a class="header-anchor" href="#_7-erweiterungsrichtungen-von-technologie-und-energie" aria-label="Permalink to &quot;7. Erweiterungsrichtungen von Technologie und Energie&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nummer</th><th>Erweiterungsrichtung</th><th>Wert der Erweiterung</th><th>Zugehörige Einstellung</th><th>Kreativer Vorschlag</th></tr></thead><tbody><tr><td>E24</td><td>Detaillierte Prinzipien einer einzelnen Technologie</td><td>Detaillierte Analyse der Prinzipien einer Schlüsseltechnologie (wie Kopierspiegel, isolierter Raum, Ingenieurwesen der Bei-Zeng-Frucht)</td><td>Dokument 60-69, Dokument 63-64</td><td>Man kann die Entwicklungsgeschichte der Technologie, die Kernkomponenten, den Arbeitsablauf, die technischen Grenzen, die Upgrade-Richtungen usw. einstellen</td></tr><tr><td>E25</td><td>Detaillierte Klassifizierung von Kultivierungsinstrumenten</td><td>Einstellung der Klassifizierung, Funktion, des Grades und der Verwendungsmethode verschiedener Kultivierungshilfsinstrumente</td><td>Dokument 61, Dokument 67</td><td>Man kann Arten von Instrumenten wie &quot;Kultivierungskapsel&quot;, &quot;Gesetzesdetektor&quot;, &quot;Energiewandler&quot;, &quot;Bewusstseinsverstärker&quot; einstellen</td></tr><tr><td>E26</td><td>Detaillierte Einstellung der Anker-Hardware</td><td>Detaillierte Einstellung der Struktur, Funktion, des Baus und der Wartung der Anker-Hardwareeinrichtungen</td><td>Dokument 20, Dokument 67</td><td>Man kann die Kernkomponenten künstlicher Anker, die Energieversorgung, den Wartungszyklus, die Fehlerbehandlung usw. einstellen</td></tr><tr><td>E27</td><td>Interplanare Kommunikationstechnologie</td><td>Detaillierte Einstellung der technischen Prinzipien, Gerätetypen, Kommunikationsprotokolle und Sicherheitsmechanismen der interplanaren Kommunikation</td><td>Dokument 66, Dokument 81</td><td>Man kann verschiedene Kommunikationsmethoden wie &quot;Ankerwellenkommunikation&quot;, &quot;Raumfaltkommunikation&quot;, &quot;Bewusstseinsresonanzkommunikation&quot; einstellen</td></tr></tbody></table><h2 id="_8-erweiterungsrichtungen-von-geschichte-und-ereignissen" tabindex="-1">8. Erweiterungsrichtungen von Geschichte und Ereignissen <a class="header-anchor" href="#_8-erweiterungsrichtungen-von-geschichte-und-ereignissen" aria-label="Permalink to &quot;8. Erweiterungsrichtungen von Geschichte und Ereignissen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nummer</th><th>Erweiterungsrichtung</th><th>Wert der Erweiterung</th><th>Zugehörige Einstellung</th><th>Kreativer Vorschlag</th></tr></thead><tbody><tr><td>E28</td><td>Detaillierte Erzählung wichtiger historischer Ereignisse</td><td>Detaillierte historische Erzählung eines wichtigen Ereignisses in der Chronik</td><td>Dokument 70-79, Dokument 93</td><td>Man kann den gesamten Prozess von Ereignissen wie dem &quot;Ereignis der Öffnung der dreihundert Systeme&quot;, der &quot;Umsetzung der 20%-Aktivierungsstrategie&quot;, dem &quot;Meilenstein der ersten Dimensionserhöhung&quot; detailliert erzählen</td></tr><tr><td>E29</td><td>Biographien historischer Persönlichkeiten</td><td>Verfassen detaillierter Biographien für Schlüsselpersonen, um die menschliche Tiefe der Geschichte zu bereichern</td><td>Dokument 95</td><td>Man kann Biographien für Schlüsselpersonen wie &quot;Xuan Hengzi&quot;, &quot;Gongshengzi&quot;, &quot;Lixiangong&quot;, &quot;Sanbaishi&quot; verfassen</td></tr><tr><td>E30</td><td>Hypothetische Analyse historischer Wendepunkte</td><td>Analyse, wie sich die Entwicklung der Symbiose-Zivilisation unterscheiden würde, wenn ein historisches Ereignis in eine andere Richtung gegangen wäre</td><td>Dokument 70-79</td><td>Man kann hypothetische Analysen wie &quot;wenn die Symbiose-Verfassung nicht verabschiedet worden wäre&quot;, &quot;wenn die 20%-Aktivierungsstrategie gescheitert wäre&quot; durchführen, um die Kontingenz der Geschichte zu zeigen</td></tr><tr><td>E31</td><td>Detaillierte Aufzeichnungen archäologischer Entdeckungen</td><td>Einstellung der detaillierten Entdeckungen und Forschungsergebnisse einer interplanaren Archäologie</td><td>Dokument 84-87</td><td>Man kann Dinge wie &quot;archäologische Entdeckung einer verlorenen Zivilisation&quot;, &quot;Ergebnisse der Zeitrückwärtsarchäologie eines wichtigen historischen Knotens&quot; einstellen</td></tr></tbody></table><h2 id="_9-erweiterungsrichtungen-von-interplanar-und-zeit" tabindex="-1">9. Erweiterungsrichtungen von Interplanar und Zeit <a class="header-anchor" href="#_9-erweiterungsrichtungen-von-interplanar-und-zeit" aria-label="Permalink to &quot;9. Erweiterungsrichtungen von Interplanar und Zeit&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nummer</th><th>Erweiterungsrichtung</th><th>Wert der Erweiterung</th><th>Zugehörige Einstellung</th><th>Kreativer Vorschlag</th></tr></thead><tbody><tr><td>E32</td><td>Detaillierte Einstellung einer spezifischen Ebene</td><td>Einstellung der Gesetzparameter, der Zivilisationsform, der geografischen Umgebung und der Geschichte einer spezifischen Ebene</td><td>Dokument 80, Dokument 81</td><td>Man kann verschiedene Arten spezifischer Ebenen wie &quot;hohe Magie-Ebene&quot;, &quot;Technologie-Ebene&quot;, &quot;wilde Ebene&quot;, &quot;Bewusstseinsebene&quot; einstellen</td></tr><tr><td>E33</td><td>Fälle interplanarer Diplomatie</td><td>Einstellung spezifischer Fälle der Aufnahme diplomatischer Beziehungen zwischen der Symbiose-Zivilisation und anderen Zivilisationen anderer Ebenen</td><td>Dokument 81, Dokument 88</td><td>Man kann spezifische diplomatische Ereignisse wie Erstkontakt, Verhandlungen zur Aufnahme von Beziehungen, Kulturaustausch, Handelsabkommen einstellen</td></tr><tr><td>E34</td><td>Spezifische Fälle der Zeitrückwärtsbewegung</td><td>Einstellung des spezifischen Prozesses, der Entdeckungen und der Auswirkungen einer Zeitrückwärtsoperation</td><td>Dokument 82-83, Dokument 89</td><td>Man kann Fälle wie die &quot;Rückwärtslösung eines historischen Rätsels&quot;, die &quot;Rückwärtswiederherstellung einer untergegangenen Zivilisation&quot; einstellen</td></tr><tr><td>E35</td><td>Detaillierte Aufzeichnungen von Zeitparadox-Ereignissen</td><td>Einstellung des gesamten Prozesses des Auftretens, der Notfallreaktion und der Kausalreparatur eines Zeitparadox-Ereignisses</td><td>Dokument 89</td><td>Man kann eine vollständige Behandlungsaufzeichnung eines kleinen Paradox-Ereignisses verfassen, um den praktischen Betrieb des Präventions- und Kontrollmechanismus zu zeigen</td></tr><tr><td>E36</td><td>Interplanare Konflikte und ihre Lösung</td><td>Einstellung der Konflikte zwischen der Symbiose-Zivilisation und anderen Zivilisationen anderer Ebenen und ihres friedlichen Lösungsprozesses</td><td>Dokument 81, Dokument 88</td><td>Man kann verschiedene Arten von Fällen interplanarer Konflikte wie Ressourcenstreitigkeiten, Kulturkonflikte, Grenzstreitigkeiten einstellen</td></tr></tbody></table><h2 id="_10-schopferische-prinzipien-fur-erweiterte-einstellungen" tabindex="-1">10. Schöpferische Prinzipien für erweiterte Einstellungen <a class="header-anchor" href="#_10-schopferische-prinzipien-fur-erweiterte-einstellungen" aria-label="Permalink to &quot;10. Schöpferische Prinzipien für erweiterte Einstellungen&quot;">​</a></h2><p>Bei der Durchführung der schöpferischen Arbeit an erweiterten Einstellungen sollten die folgenden Prinzipien befolgt werden:</p><ol><li><strong>Konsistenz优先</strong>: Alle erweiterten Einstellungen müssen die logische Konsistenz mit den bestehenden Einstellungen wahren und die Prüfung der Selbstprüfungstabelle für Einstellungswidersprüche bestehen.</li><li><strong>Auf der Realität basierend</strong>: Erweiterte Einstellungen sollten auf objektiven Gesetzen beruhen, um vernünftig zu deduzieren, und reine Phantasie sowie den Zusammenbruch der Einstellungen vermeiden.</li><li><strong>Position der Symbiose</strong>: Erweiterte Einstellungen sollten immer die Kernposition der Anti-Plünderung und der Befürwortung der Symbiose beibehalten und dürfen plünderndes Verhalten nicht verteidigen.</li><li><strong>Offenheit</strong>: Erweiterte Einstellungen sollten ein gewisses Maß an Offenheit bewahren, um Raum für weitere Erweiterungen in der Zukunft zu lassen.</li><li><strong>Praktikabilität</strong>: Erweiterte Einstellungen sollten einen praktischen schöpferischen Wert haben und in der Lage sein, nützliches Material für das Geschichtenerzählen, das Spieldesign und die theoretische Diskussion bereitzustellen.</li></ol><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Die Liste der Vorschläge für erweiterte Einstellungen ist die &quot;offene Tür&quot; des Einstellungssystems der Anker-Symbiose-Zivilisation. Sie zeigt, dass dieses Einstellungssystem kein geschlossenes, fertiges Produkt ist, sondern ein lebendiges System, das ständig wächst und sich ständig bereichert. Die sechsunddreißig Erweiterungsrichtungen sind nur der Ausgangspunkt; die wahre schöpferische Kraft der Einstellungen entspringt der Vorstellungskraft und Leidenschaft jedes Teilnehmers. Solange die grundlegenden Prinzipien der Konsistenz der Einstellungen befolgt werden, wird jede wertvolle Erweiterung zu einem unverzichtbaren Bestandteil der großen Erzählung der Anker-Symbiose-Zivilisation werden.</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>97-Selbstprüfungstabelle für Einstellungswidersprüche</li><li>99-Versions- und Wartungsanleitung für Dokumente</li><li>96-Häufig gestellte Fragen FAQ</li></ul>',27)])])}const m=n(s,[["render",d]]);export{c as __pageData,m as default};
